"Il bacino resta basso e stabile.": "Das Becken bleibt tief und stabil.",
"Il bacino resta fermo come se fosse dentro una cintura rigida.": "Das Becken bleibt ruhig, als stecke es in einem festen Gürtel.",
"Il bacino resta fermo: si muove la colonna.": "Das Becken bleibt ruhig: die Wirbelsäule bewegt sich.",
"Il bacino resta incollato allo schienale: è lui a dirti dove fermarti.": "Das Becken bleibt an der Lehne: es zeigt dir, wo du stoppst.",
"Il bilanciere sfiora le gambe per tutta la salita.": "Die Stange streift auf dem ganzen Weg nach oben die Beine.",
"Il braccio resta fermo parallelo al busto.": "Der Oberarm bleibt ruhig, parallel zum Oberkörper.",
"Il busto è una tavola ferma: si muovono solo braccia e scapole.": "Der Oberkörper ist ein ruhiges Brett: nur Arme und Schulterblätter bewegen sich.",
"Il calendario e vuoto: metti prima la settimana tipo sul mese.": "Der Kalender ist leer: setz zuerst deine Standardwoche in den Monat.",
"Il carico e sotto il peso del bilanciere.": "Die Last liegt unter dem Gewicht der Stange.",
"Il carico progressivo aumentera i pesi quando completi tutte le serie, e li alleggerira nelle settimane di scarico.": "Die Laststeigerung erhöht die Gewichte, wenn du alle Sätze schaffst, und senkt sie in Entlastungswochen.",
"Il classico #-# ripetizioni, con aumento graduale del carico settimana dopo settimana.": "Die klassischen #-# Wiederholungen, mit schrittweiser Laststeigerung Woche für Woche.",
