"Il coach usa i tuoi dati (obiettivi, BIA, storico) e per questo serve il tuo consenso.": "Der Coach nutzt deine Daten (Ziele, BIA, Verlauf), deshalb braucht es deine Einwilligung.",
"Il coach usa questionario, BIA e storico solo su questo telefono.": "Der Coach nutzt Fragebogen, BIA und Verlauf nur auf diesem Handy.",
