"Il massimale stimato e calcolato con la formula di Epley: una stima, non un test da fare.": "Das geschätzte Maximum wird mit der Epley-Formel berechnet: eine Schätzung, kein Test.",
"Il mese reale: scambia i giorni nella stessa settimana, copia una settimana, esporta verso il calendario del telefono.": "Der echte Monat: Tage innerhalb derselben Woche tauschen, eine Woche kopieren, in den Handykalender exportieren.",
"Il mignolo non va più in alto del pollice.": "Der kleine Finger kommt nicht höher als der Daumen.",
"Il mignolo sale verso la spalla: la supinazione completa accende il bicipite.": "Der kleine Finger steigt zur Schulter: die volle Supination aktiviert den Bizeps.",
"Il movimento parte dall anca, non dalla schiena: il sedere va indietro.": "Die Bewegung beginnt in der Hüfte, nicht im Rücken: der Po geht nach hinten.",
