"In piedi davanti al cavo alto, barra dritta o corda, busto leggermente inclinato, braccia quasi tese.": "Stehend vor dem oberen Kabel, gerade Stange oder Seil, Oberkörper leicht geneigt, Arme fast gestreckt.",
