"In piedi, bilanciere sulle clavicole, presa appena più larga delle spalle, glutei e addome contratti.": "Stehend, Stange auf den Schlüsselbeinen, Griff knapp breiter als schulterbreit, Gesäß und Bauch angespannt.",
"In piedi, busto dritto, manubri ai fianchi o mani sui fianchi.": "Stehend, Oberkörper aufrecht, Hanteln seitlich oder Hände an den Hüften.",
"In piedi, manubri ai lati, gomiti leggermente flessi, busto leggermente in avanti.": "Stehend, Hanteln seitlich, Ellbogen leicht gebeugt, Oberkörper leicht vorgeneigt.",
