"Pensa a \\\"piegare il bilanciere\\\" con le mani: attiva i dorsali e stabilizza le spalle.": "Stell dir vor, du \"biegst die Stange\" mit den Händen: das aktiviert den Latissimus und stabilisiert die Schultern.",
