"Piede avanti troppo vicino alla panca.": "Vorderer Fuß zu nah an der Bank.",
"Piede dietro appoggiato su una panca, piede avanti a circa un passo e mezzo.": "Hinterer Fuß auf einer Bank, vorderer Fuß etwa eineinhalb Schritte entfernt.",
"Piedi ai lati della barra, anche indietro, busto a circa #°, schiena neutra, presa neutra (palmi che si guardano).": "Füße links und rechts der Stange, Hüfte nach hinten, Oberkörper bei etwa #°, Rücken neutral, Neutralgriff (Handflächen zueinander).",
"Piedi alla larghezza delle anche, bilanciere sopra la metà del piede. Piegati prendendo il bilanciere appena fuori dalle gambe: tibie che lo toccano, schiena in posizione neutra (curve naturali), spalle leggermente davanti al bilanciere.": "Füße hüftbreit, Stange über der Fußmitte. Beug dich runter und greif die Stange knapp außerhalb der Beine: Schienbeine berühren sie, Rücken neutral (natürliche Krümmungen), Schultern leicht vor der Stange.",
"Piedi larghi come le spalle, punte leggermente in fuori.": "Füße schulterbreit, Zehen leicht nach außen.",
"Piedi molto larghi con punte in fuori, presa stretta dentro le gambe, busto più verticale che nello stacco classico.": "Sehr breiter Stand mit Zehen nach außen, enger Griff innerhalb der Beine, Oberkörper aufrechter als beim klassischen Kreuzheben.",
"Piedi più in basso = più quadricipiti; più in alto = più glutei.": "Füße tiefer = mehr Quadrizeps; höher = mehr Gesäß.",
"Piedi su due binari, non su una corda.": "Füße auf zwei Schienen, nicht auf einem Seil.",
"Piedi troppo lontani (lavorano i femorali) o troppo vicini (lavorano i quadricipiti).": "Füße zu weit weg (Beinbeuger arbeiten) oder zu nah (Quadrizeps arbeitet).",
"Piega i gomiti mantenendo la presa neutra.": "Beug die Ellbogen und behalte den Neutralgriff.",
"Piega i gomiti portando il bilanciere verso le spalle.": "Beug die Ellbogen und bring die Stange zu den Schultern.",
"Piega i gomiti portando il peso verso la fronte o dietro la testa.": "Beug die Ellbogen und bring das Gewicht zur Stirn oder hinter den Kopf.",
"Piega i gomiti portando il peso verso le spalle.": "Beug die Ellbogen und bring das Gewicht zu den Schultern.",
"Piega i gomiti portando la barra verso il petto.": "Beug die Ellbogen und bring die Stange zur Brust.",
"Piega il gomito portando il manubrio verso la spalla.": "Beug den Ellbogen und bring die Hantel zur Schulter.",
"Piega le ginocchia portando i talloni sotto il sedile.": "Beug die Knie und bring die Fersen unter den Sitz.",
