"Porta a cedimento": "Bis zum Muskelversagen",
"Porta i talloni verso i glutei.": "Bring die Fersen zum Gesäß.",
"Porta il manubrio dietro la testa con un arco, finché le braccia sono in linea con il busto.": "Führ die Hantel im Bogen hinter den Kopf, bis die Arme in Linie mit dem Oberkörper sind.",
"Porta il petto verso la sbarra, non il mento.": "Bring die Brust zur Stange, nicht das Kinn.",
"Porta la barra verso le cosce con un arco, braccia quasi distese.": "Führ die Stange im Bogen zu den Oberschenkeln, Arme fast gestreckt.",
"Porta la serie # a cedimento": "Satz # bis zum Muskelversagen",
"Porta le anche indietro (hip hinge) facendo scendere il bilanciere lungo le cosce.": "Schieb die Hüfte nach hinten (Hip Hinge) und lass die Stange an den Oberschenkeln entlang sinken.",
"Porta le anche indietro e inclina il busto in avanti con la schiena neutra.": "Schieb die Hüfte nach hinten und neig den Oberkörper mit neutralem Rücken nach vorn.",
"Porta le braccia davanti a te fino a far quasi toccare le maniglie.": "Führ die Arme vor dir zusammen, bis sich die Griffe fast berühren.",
"Porta le mani una verso l'altra davanti al petto con un arco ampio.": "Führ die Hände in einem weiten Bogen vor der Brust zusammen.",
"Porta un ginocchio verso il petto e torna indietro alternando.": "Zieh abwechselnd ein Knie zur Brust und zurück.",
