"Posizione di partenza": "Ausgangsposition",
"Premi i talloni come se volessi trascinarli verso di te.": "Drück die Fersen, als wolltest du sie zu dir ziehen.",
"Premi la zona lombare a terra.": "Drück den unteren Rücken in den Boden.",
"Prendo l ultimo carico che hai usato e ne calcolo l #%. E un riferimento pratico per le serie in cui vuoi restare a circa due ripetizioni dal cedimento: utile nelle giornate storte o nelle settimane di scarico. Formula: ultimo carico × #.": "Ich nehme die zuletzt genutzte Last und berechne #% davon. Ein praktischer Richtwert für Sätze, bei denen du etwa zwei Wiederholungen vor dem Muskelversagen bleiben willst: nützlich an schlechten Tagen oder in Entlastungswochen. Formel: letzte Last × #.",
"Presa prona (palmi in avanti) poco più larga delle spalle, braccia tese, core contratto e gambe unite.": "Obergriff (Handflächen nach vorn) etwas breiter als schulterbreit, Arme gestreckt, Rumpf angespannt, Beine geschlossen.",
"Presa stretta e gomiti sopra le spalle: aumentano il rischio di conflitto (impingement) nella spalla.": "Enger Griff und Ellbogen über den Schultern: das erhöht das Risiko eines Impingements in der Schulter.",
"Presa supina (palmi verso di te) alla larghezza delle spalle, braccia tese.": "Untergriff (Handflächen zu dir) schulterbreit, Arme gestreckt.",
"Presa supina alla larghezza delle spalle, cosce bloccate, petto alto.": "Schulterbreiter Untergriff, Oberschenkel fixiert, Brust raus.",
"Presa troppo stretta: stress sui polsi.": "Griff zu eng: Belastung der Handgelenke.",
