"Scegli almeno un esercizio": "Wähle mindestens eine Übung",
"Scegli almeno un giorno": "Wähle mindestens einen Tag",
"Scegli con la ruota": "Mit dem Rad wählen",
"Scegli i muscoli da allenare e poi gli esercizi, uno per uno.": "Wähle die Muskeln und dann die Übungen, eine nach der anderen.",
"Scegli il numero": "Zahl wählen",
"Scegli il punto di partenza: verranno riprodotti # secondi esatti.": "Wähle den Startpunkt: es werden genau # Sekunden abgespielt.",
"Scegli un allenamento": "Wähle ein Training",
"Scegli un altro giorno": "Anderen Tag wählen",
"Scendere a scatto: stress sul gomito.": "Ruckartig absenken: Belastung für den Ellbogen.",
"Scendere sotto la linea del busto.": "Unter die Rumpflinie gehen.",
"Scendere troppo in basso perdendo le scapole: spalla in avanti.": "Zu tief gehen und die Schulterblätter verlieren: die Schulter rollt nach vorn.",
"Scendere troppo in basso: stress sulla capsula anteriore della spalla.": "Zu tief gehen: Belastung der vorderen Schulterkapsel.",
"Scendere troppo veloce.": "Zu schnell absenken.",
"Scendere troppo: il bacino si stacca e la zona lombare si arrotonda.": "Zu tief gehen: das Becken hebt ab und der untere Rücken rundet sich.",
"Scendere troppo: stress sulla spalla anteriore.": "Zu tief gehen: Belastung der vorderen Schulter.",
"Scendi con i gomiti a circa #° dal corpo.": "Senk dich mit den Ellbogen etwa #° vom Körper ab.",
"Scendi con i gomiti vicini al busto verso la parte bassa del petto.": "Senk die Stange mit den Ellbogen nah am Oberkörper zur unteren Brust.",
"Scendi con i talloni fino al massimo allungamento.": "Senk die Fersen bis zur maximalen Dehnung.",
"Scendi con i talloni sotto il livello del gradino (dorsiflessione) per allungare il polpaccio.": "Senk die Fersen unter die Stufe (Dorsalflexion), um die Wade zu dehnen.",
"Scendi controllando fino a sfiorare il petto.": "Senk kontrolliert ab, bis du die Brust leicht berührst.",
"Scendi controllando verso la parte alta del petto, sotto le clavicole.": "Senk kontrolliert zur oberen Brust ab, unter die Schlüsselbeine.",
"Scendi controllando, senza lasciarti cadere.": "Senk kontrolliert ab, ohne dich fallen zu lassen.",
"Scendi controllato con la stessa gamba.": "Steig kontrolliert mit demselben Bein ab.",
"Scendi controllato fino a braccia distese senza cambiare l'angolo del busto.": "Senk kontrolliert ab, bis die Arme gestreckt sind, ohne den Oberkörperwinkel zu ändern.",
"Scendi controllato fino a braccia distese.": "Senk kontrolliert ab, bis die Arme gestreckt sind.",
"Scendi controllato fino all'altezza delle spalle.": "Senk kontrolliert bis auf Schulterhöhe ab.",
"Scendi controllato senza oscillare.": "Senk kontrolliert ab, ohne zu schwingen.",
"Scendi controllato verso la parte bassa del petto.": "Senk kontrolliert zur unteren Brust ab.",
"Scendi controllato.": "Senk kontrolliert ab.",
"Scendi controllato: il cavo tiene la tensione costante.": "Senk kontrolliert ab: das Kabel hält die Spannung konstant.",
"Scendi finche il ginocchio dietro sfiora quasi terra.": "Geh runter, bis das hintere Knie fast den Boden berührt.",
"Scendi finché i manubri sono all'altezza del petto, gomiti a #° dal busto: il pettorale si allunga più che col bilanciere.": "Senk ab, bis die Hanteln auf Brusthöhe sind, Ellbogen #° vom Rumpf: die Brust wird stärker gedehnt als mit der Langhantel.",
"Scendi finché senti i femorali in tensione, busto quasi parallelo o poco sopra.": "Geh runter, bis du Spannung in den Beinbeugern spürst, Oberkörper fast parallel oder etwas darüber.",
"Scendi finché senti tirare i femorali, di solito a metà tibia, schiena sempre neutra.": "Senk ab, bis du die Beinbeuger ziehen spürst, meist bis zur Schienbeinmitte, Rücken immer neutral.",
"Scendi fino a braccio disteso, lasciando allungare il dorsale.": "Senk ab, bis der Arm gestreckt ist, und lass den Latissimus dehnen.",
"Scendi fino all'altezza delle orecchie o delle spalle.": "Senk bis auf Ohr- oder Schulterhöhe ab.",
"Scendi in verticale finché la coscia avanti è parallela al pavimento.": "Geh senkrecht runter, bis der vordere Oberschenkel parallel zum Boden ist.",
"Scendi in verticale, come in un ascensore.": "Geh senkrecht runter, wie in einem Aufzug.",
"Scendi invertendo il movimento: prima le anche indietro, poi le ginocchia.": "Senk ab, indem du die Bewegung umkehrst: zuerst Hüfte nach hinten, dann die Knie.",
"Scendi lentamente e alterna.": "Senk langsam ab und wechsle.",
"Scendi lentamente fermandoti prima che la schiena si inarchi.": "Senk langsam ab und stopp, bevor der Rücken ins Hohlkreuz geht.",
"Scendi lentamente fino a braccia quasi distese.": "Senk langsam ab, bis die Arme fast gestreckt sind.",
"Scendi lentamente fino quasi a braccia tese.": "Senk langsam ab bis fast zu gestreckten Armen.",
"Scendi lentamente in #–# secondi.": "Senk langsam in #–# Sekunden ab.",
"Scendi lentamente senza distendere di colpo.": "Senk langsam ab, ohne ruckartig zu strecken.",
"Scendi lentamente senza far toccare i pesi.": "Senk langsam ab, ohne dass die Gewichte aufsetzen.",
"Scendi lentamente senza perdere la schiena neutra.": "Senk langsam ab, ohne den neutralen Rücken zu verlieren.",
"Scendi lentamente sotto il livello del gradino.": "Senk langsam unter Stufenhöhe ab.",
"Scendi lentamente.": "Senk langsam ab.",
"Scendi mandando il sedere indietro e in basso, come per sederti.": "Geh runter, indem du den Po nach hinten und unten schiebst, wie zum Hinsetzen.",
"Scendi mantenendo i gomiti alti.": "Geh runter und halte die Ellbogen hoch.",
"Scendi piegando i gomiti finché le spalle arrivano all'altezza dei gomiti (circa #°).": "Senk dich durch Beugen der Ellbogen ab, bis die Schultern auf Ellbogenhöhe sind (etwa #°).",
"Scendi piegando i gomiti fino a circa #°.": "Senk dich ab, indem du die Ellbogen auf etwa #° beugst.",
"Scendi piegando insieme anche e ginocchia, come per sederti tra i talloni.": "Geh runter, indem du Hüfte und Knie gleichzeitig beugst, als würdest du dich zwischen die Fersen setzen.",
"Scendi piegando le anche con la schiena neutra.": "Senk dich durch Beugen der Hüfte mit neutralem Rücken ab.",
"Scendi tra le gambe tenendo il busto dritto.": "Geh zwischen die Beine runter und halte den Oberkörper aufrecht.",
