"Servono almeno due sedute per disegnare l andamento.": "Mindestens zwei Einheiten sind nötig, um den Verlauf zu zeichnen.",
"Servono per interpretare i valori: le soglie della massa grassa sono diverse per uomini e donne.": "Nötig zur Auswertung: Die Körperfett-Grenzwerte sind für Männer und Frauen unterschiedlich.",
