"Dopo il primo allenamento il grafico parte da qui.": "Nach dem ersten Training beginnt hier das Diagramm.",
"Primo punto: dal prossimo peso vedi la linea.": "Erster Punkt: Ab dem nächsten Wiegen siehst du die Linie.",
