"Il livello dipende da quanto e come ti alleni: dopo qualche settimana il coach lo verifica sul tuo storico.": "Dein Level hängt davon ab, wie viel und wie du trainierst: Nach ein paar Wochen prüft der Coach es anhand deines Verlaufs.",
"Livello:": "Level:",
"Spingi via il pavimento con tutto il piede.": "Drück den Boden mit dem ganzen Fuß weg.",
"Fianchi indietro come per chiudere una porta, poi spingili avanti.": "Hüfte nach hinten, als würdest du eine Tür schließen, dann nach vorn schieben.",
"Allontana il peso da te, come per spingere via la panca.": "Drück das Gewicht von dir weg, als würdest du die Bank wegschieben.",
"Spingi il peso verso il soffitto e passa con la testa sotto.": "Drück das Gewicht zur Decke und bring den Kopf darunter.",
"Porta i gomiti verso i fianchi.": "Zieh die Ellbogen zur Hüfte.",
"Porta i gomiti verso le tasche.": "Zieh die Ellbogen zu den Hosentaschen.",
"Senti il muscolo che lavora: discesa in 2–3 secondi.": "Spür den Muskel arbeiten: in 2–3 Sekunden absenken.",
"Stessa ampiezza a ogni seduta: così i carichi sono confrontabili.": "Gleicher Bewegungsumfang jede Einheit: So sind die Gewichte vergleichbar.",
"La tua posizione:": "Deine Position:",
"piedi alla larghezza delle anche": "Füße hüftbreit",
"piedi alla larghezza delle spalle": "Füße schulterbreit",
"piedi più larghi delle spalle, punte aperte": "Füße breiter als schulterbreit, Fußspitzen nach außen",
"Caviglia rigida: talloni su due dischi sottili.": "Steife Knöchel: Fersen auf zwei dünnen Scheiben.",
"Non trattenere il fiato: espira mentre sollevi, inspira in discesa. Carichi moderati, 8–12 ripetizioni.": "Halte nicht die Luft an: beim Heben ausatmen, beim Senken einatmen. Moderate Gewichte, 8–12 Wiederholungen.",
"Pensa a": "Achte auf",
