"Test in due minuti": "Tests in zwei Minuten",
"Il coach sceglie le varianti in base al tuo corpo: talloni rialzati, spinte inclinate, larghezza dello squat.": "Der Coach wählt Varianten passend zu deinem Körper: erhöhte Fersen, schräge Drückübungen, Kniebeugenbreite.",
"Femorali: squat e hip thrust non li fanno crescere, serve la flessione del ginocchio (leg curl).": "Beinbeuger: Kniebeugen und Hip Thrust bauen sie nicht auf, es braucht Kniebeugung (Beinbeuger-Curl).",
"Retto femorale: cresce solo con la leg extension, schienale un po’ reclinato.": "Gerader Oberschenkelmuskel: wächst nur mit Beinstrecker, Lehne leicht zurückgeneigt.",
"Spalle larghe: la panca copre il deltoide anteriore, le alzate laterali quello laterale.": "Breite Schultern: Bankdrücken deckt die vordere Schulter ab, Seitheben die seitliche.",
"Bicipite: un curl su panca inclinata e uno alla Scott per crescere in tutta la lunghezza.": "Bizeps: ein Schrägbank-Curl und ein Scott-Curl für Wachstum auf ganzer Länge.",
"Caviglia: ginocchio al muro": "Knöchel: Knie zur Wand",
"Alluce a 12 cm dal muro, tallone a terra: il ginocchio tocca il muro?": "Großzeh 12 cm von der Wand, Ferse am Boden: Berührt das Knie die Wand?",
"Tocca": "Berührt",
"Non tocca": "Berührt nicht",
"Spalle: braccia al muro": "Schultern: Arme an der Wand",
"Schiena e braccia al muro, porta le braccia in alto senza staccarle: ci riesci?": "Rücken und Arme an der Wand, Arme heben ohne sie zu lösen: Schaffst du es?",
"Squat: la tua larghezza": "Kniebeuge: deine Breite",
"Prova tre larghezze a corpo libero: tieni quella dove scendi di più senza fastidi.": "Probiere drei Breiten ohne Gewicht: Behalte die, bei der du am tiefsten ohne Beschwerden kommst.",
"Stretta": "Schmal",
"Media": "Mittel",
"Larga": "Breit",
"Spalle: spinte con presa stretta o manubri a presa neutra, ampiezza senza dolore. Si torna al pieno quando il fastidio cala.": "Schultern: Drücken mit engem Griff oder Kurzhanteln im Neutralgriff, schmerzfreier Umfang. Zurück zum vollen Umfang, wenn die Beschwerden nachlassen.",
"Ginocchia: prima delle gambe leg extension isometrica 5 × 45 s (dolore fino a 3/10), discesa in 3–4 s, profondità senza dolore.": "Knie: vor den Beinen isometrischer Beinstrecker 5 × 45 s (Schmerz bis 3/10), 3–4 s absenken, schmerzfreie Tiefe.",
"Schiena bassa: riscaldamento McGill (curl-up, plank laterale, bird dog), tenute di 8-6-4 secondi.": "Unterer Rücken: McGill-Aufwärmen (Curl-up, Seitstütz, Bird Dog), Halten 8-6-4 Sekunden.",
