"Parte dal 120% e si adatta ogni settimana: serie facili la alzano, stanchezza, dolore o sedute saltate la abbassano.": "Startet bei 120% und passt sich jede Woche an: leichte Sätze erhöhen ihn, Müdigkeit, Schmerzen oder ausgelassene Einheiten senken ihn.",
