"Esercizi personalizzati": "Eigene Übungen",
"Restano con il nome che hai scritto: li vedi nello storico e nelle statistiche.": "Sie behalten den Namen, den du geschrieben hast: Du siehst sie im Verlauf und in der Statistik.",
